{
     "title": "CSCI-142: Computer Science II - Object-Oriented Foundations",
     "learningObjectives": [
       "Define and distinguish between static and dynamic data types in object-oriented programming.",
       "Explain how inheritance and interfaces enable code reuse and modifiability in software design.",
       "Apply cohesion and minimal coupling principles to structure object-oriented collections and handle exceptions."
     ],
     "beats": [
       {
         "title": "Course Scope and Ethical Practice",
         "claim": "CSCI-142 builds on CSCI-141 by advancing problem-solving through object-oriented design, while requiring professionals to uphold ethical standards like honesty and respect for work",
         "example": "Students will review the ACM Code of Ethics to understand how computing professionals must avoid harm and maintain high professional competence",
         "visualDirection": "Display a split-screen graphic: left side shows the ACM Code of Ethics excerpt, right side shows a checklist of ethical decision-making steps",
         "sourceIds": ["acm-code-of-ethics"]
       },
       {
         "title": "Responsible Technical Communication",
         "claim": "Effective technical communication in computer science requires distinguishing claims from evidence and citing prior work to maintain research integrity",
         "example": "Instructor will demonstrate how to structure a lab report that clearly separates observed results from theoretical claims, ensuring reproducibility",
         "visualDirection": "Show a before-and-after comparison of a paragraph: first version lacks citations and conflates evidence with claims, second version uses proper attribution and clear separation",
         "sourceIds": ["acm-research-practice"]
       },
       {
         "title": "Static vs. Dynamic Data Types",
         "claim": "Object-oriented programming distinguishes static data types, which are resolved at compile time, from dynamic data types, which are resolved at runtime",
         "example": "A variable declared as int in Java is static and checked during compilation, whereas a variable assigned a new object reference at runtime is dynamic",
         "visualDirection": "Create a flowchart showing compile-time type checking for static types versus runtime type resolution for dynamic types, with labeled nodes",
         "sourceIds": ["rit-csci-142"]
       },
       {
         "title": "Objects and Classes as Blueprints",
         "claim": "Classes serve as blueprints for creating objects, encapsulating data and behavior to promote modifiability and maintainability",
         "example": "A class named BankAccount defines fields like balance and methods like deposit, which are instantiated into separate BankAccount objects",
         "visualDirection": "Render a UML class diagram showing a BankAccount class with fields and methods, alongside three instantiated object diagrams",
         "sourceIds": ["rit-csci-142"]
       },
       {
         "title": "Inheritance for Code Reuse",
         "claim": "Inheritance allows subclasses to inherit attributes and methods from parent classes, reducing redundancy and enhancing modifiability",
         "example": "A Vehicle class defines speed and color, while a Car class inherits these properties and adds a method for honking",
         "visualDirection": "Draw a hierarchical inheritance diagram with Vehicle at the root and Car, Truck, and Bicycle as child nodes, connected by solid lines",
         "sourceIds": ["rit-csci-142"]
       },
       {
         "title": "Interfaces for Contractual Design",
         "claim": "Interfaces define a set of methods that classes must implement, enabling minimal coupling and flexible extensibility across unrelated classes",
         "example": "A PaymentProcessor interface requires implement classes like CreditCard and PayPal to provide a processPayment method",
         "visualDirection": "Show a diagram of a PaymentProcessor interface with dashed arrows pointing to CreditCard and PayPal classes, labeled as implementations",
         "sourceIds": ["rit-csci-142"]
       },
       {
         "title": "Object-Oriented Collections and ADTs",
         "claim": "Object-oriented collection class libraries provide abstract data types like stacks, queues, maps, and trees, enabling efficient data management",
         "example": "A Stack class supports push and pop operations, while a Map class stores key-value pairs for fast retrieval",
         "visualDirection": "Display four icons representing Stack, Queue, Map, and Tree structures, each with a brief label and a small code snippet showing usage",
         "sourceIds": ["rit-csci-142"]
       },
       {
         "title": "Software Qualities: Cohesion and Minimal Coupling",
         "claim": "High cohesion groups related data and behavior within a class, while minimal coupling reduces dependencies between classes to improve modifiability",
         "example": "A GraphicsManager class handles rendering tasks, while a InputHandler class manages user events, keeping responsibilities separate",
         "visualDirection": "Create a block diagram showing two separate modules with clear boundaries, labeled with cohesion and coupling metrics",
         "sourceIds": ["rit-csci-142"]
       },
       {
         "title": "Exception Handling and I/O Streams",
         "claim": "Exception handling allows programs to manage errors gracefully, while input and output streams enable data exchange with external systems",
         "example": "A try-catch block catches a FileNotFoundException, and a BufferedReader reads lines from a text file into memory",
         "visualDirection": "Show a control flow diagram with a try block, catch block, and finally block, alongside a stream diagram showing data flow from file to program",
         "sourceIds": ["rit-csci-142"]
       },
       {
         "title": "IDE Integration and Project Workflow",
         "claim": "Modern integrated software development environments provide tools for coding, debugging, and testing, supporting extensibility and professional practice",
         "example": "Students will use an IDE to compile code, run unit tests, and view error messages, aligning with ethical and reproducible development practices",
         "visualDirection": "Display a screenshot of an IDE interface with highlighted regions for code editor, debugger, and terminal, annotated with workflow steps",
         "sourceIds": ["rit-csci-142"]
       }
     ]
   }
